export const fmtHTG = (n) =>
  new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n??0)+' HTG';
export const fmtUSD = (n) =>
  new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n??0)+' USD';
export const fmt = (n, currency='HTG') => currency==='USD' ? fmtUSD(n) : fmtHTG(n);
export const toHTG = (amount, currency, rate) => currency==='USD' ? Number(amount)*rate : Number(amount);
export const toLocalISODate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth()+1).padStart(2,'0');
  const day = String(d.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
};
export const today = () => toLocalISODate(new Date());

// Lundi -> dimanche de la semaine contenant `d` (aujourd'hui par defaut).
export const weekRange = (d = new Date()) => {
  const day = d.getDay(); // 0=dim,1=lun,...6=sam
  const diffToMonday = day === 0 ? -6 : 1 - day;
  const monday = new Date(d.getFullYear(), d.getMonth(), d.getDate() + diffToMonday);
  const sunday = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + 6);
  return { start: toLocalISODate(monday), end: toLocalISODate(sunday) };
};

// 1er -> dernier jour du mois calendaire contenant `d`.
export const monthRange = (d = new Date()) => {
  const first = new Date(d.getFullYear(), d.getMonth(), 1);
  const last = new Date(d.getFullYear(), d.getMonth() + 1, 0);
  return { start: toLocalISODate(first), end: toLocalISODate(last) };
};
export const MONTHS_FR = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'];
export const computeBalance = (account, transactions) => {
  let balance = Number(account.initialBalance)||0;
  transactions
    .filter(t=>(t.debitAccount===account.id||t.creditAccount===account.id)&&t.status==='confirmed')
    .forEach(t=>{
      // Pour un virement entre comptes de devises differentes, `amount` est
      // le montant debite du compte source (dans sa devise) et `creditAmount`
      // le montant converti credite au compte destinataire (dans la sienne).
      // On retombe sur `amount` quand creditAmount n'existe pas (transactions
      // normales ou virements meme devise).
      if(t.creditAccount===account.id) balance += Number(t.creditAmount ?? t.amount) || 0;
      if(t.debitAccount===account.id)  balance -= Number(t.amount) || 0;
    });
  return balance;
};
// Historique complet d'un compte avec solde progressif (comme un releve
// bancaire) : toutes les transactions (tous statuts) qui touchent ce
// compte, triees du plus ancien au plus recent, avec le solde apres
// chaque mouvement confirme. Le premier point est toujours le solde de
// depart du compte (avant toute transaction).
export const accountHistory = (account, transactions) => {
  const touching = transactions.filter(t=>t.debitAccount===account.id||t.creditAccount===account.id);
  const chrono = [...touching].sort((a,b)=>a.date.localeCompare(b.date)||(a.createdAt||'').localeCompare(b.createdAt||''));
  let balance = Number(account.initialBalance)||0;
  const withRunning = chrono.map(t=>{
    const direction = t.creditAccount===account.id ? 'in' : 'out';
    // Montant a afficher/appliquer du point de vue de CE compte : pour un
    // virement cross-devise, le cote credite utilise le montant converti.
    const nativeAmount = direction==='in' ? (Number(t.creditAmount ?? t.amount)||0) : (Number(t.amount)||0);
    if(t.status==='confirmed'){
      if(direction==='in') balance+=nativeAmount; else balance-=nativeAmount;
    }
    return {...t,direction,nativeAmount,runningBalance:balance};
  });
  return withRunning;
};
export const amortize = (principal, annualRate, months) => {
  const r = annualRate/100/12;
  if(!principal||!months) return {monthly:0,totalPayment:0,totalInterest:0,schedule:[]};
  if(r===0){
    const m=principal/months;
    return {monthly:m,totalPayment:principal,totalInterest:0,
      schedule:Array.from({length:months},(_,i)=>({month:i+1,payment:m,principal:m,interest:0,balance:principal-m*(i+1)}))};
  }
  const monthly=principal*(r*Math.pow(1+r,months))/(Math.pow(1+r,months)-1);
  let balance=principal; const schedule=[];
  for(let i=1;i<=months;i++){
    const interest=balance*r, princ=monthly-interest;
    balance-=princ;
    schedule.push({month:i,payment:monthly,principal:princ,interest,balance:Math.max(0,balance)});
  }
  return {monthly,totalPayment:monthly*months,totalInterest:monthly*months-principal,schedule};
};
export const compoundSavings = (initial,monthly,annualRate,months) => {
  const r=annualRate/100/12; let balance=initial; const schedule=[];
  for(let i=1;i<=months;i++){balance=balance*(1+r)+monthly;schedule.push({month:i,balance});}
  return schedule;
};
